on conflict (id) do update set
  version = public.resources.version + case when (public.resources.name, public.resources.description, public.resources.objectives)
                                                 is distinct from (excluded.name, excluded.description, excluded.objectives) then 1 else 0 end,
  slug = excluded.slug, name = excluded.name, description = excluded.description, type = excluded.type, subject = excluded.subject,
  course_id = excluded.course_id, sport = excluded.sport, objectives = excluded.objectives, skills = excluded.skills, game_ids = excluded.game_ids,
  thumbnail = excluded.thumbnail, url = excluded.url, audience = excluded.audience, status = excluded.status, sort_order = excluded.sort_order,
  updated_at = now();

update public.resources set status = 'retired', updated_at = now()
 where status <> 'retired' and id not in ('feature.practice-engine', 'feature.teacher-curriculum', 'sport.mtb', 'sport.ski', 'sport.surf', 'sport.climb', 'course.alg1', 'course.alg2', 'course.geo', 'course.precalc', 'course.phys1', 'course.phys2', 'jump-lab', 'berm-lab', 'trail-builder', 'gear-ratio-lab', 'strava-showdown', 'carve-lab', 'slope-lab', 'jump-trajectory-lab', 'race-day-workshop', 'ride-systems-lab', 'bike-park-blueprint-lab', 'trail-dynamics-lab', 'pump-track-lab', 'enduro-route-lab', 'suspension-systems-lab', 'race-intelligence-lab', 'dream-line-project', 'intro-to-physics', 'newtons-laws', 'suspension-setup-studio', 'trail-map-navigator', 'pump-track-master', 'speed-trap', 'bike-mechanic-challenge', 'gravity-friction-run', 'kicker-air-time', 'slope-angle-finder', 'snowmaking-planner', 'gate-timing-challenge');

