  ('course.alg1', 'algebra-1', 'Algebra 1', 'Learn the fundamentals of algebra through real-world mountain biking problems involving speed, elevation, distance, jumps, and trail design.', 'course', 'Mathematics', 'alg1', null, array['Foundations of Algebra', 'Solving Equations and Inequalities', 'Linear Relationships', 'Linear Equations and Functions', 'Systems of Equations', 'Exponents and Exponential Relationships', 'Polynomials and Factoring', 'Quadratic Equations and Functions', 'Data and Statistics']::text[], array[]::text[], array[]::text[], null, 'classes/algebra-1/', 'all', 'available', 101),
  ('course.alg2', 'algebra-2', 'Algebra 2', 'Build on Algebra 1 by exploring more advanced equations, functions, polynomials, and mathematical relationships.', 'course', 'Mathematics', 'alg2', null, array['Equations and Inequalities', 'Functions', 'Linear Systems and Matrices', 'Quadratic Functions', 'Polynomial Functions', 'Rational and Radical Functions', 'Exponential and Logarithmic Functions', 'Sequences and Series', 'Probability and Statistics']::text[], array[]::text[], array[]::text[], null, 'classes/algebra-2/', 'all', 'available', 102),
  ('course.geo', 'geometry', 'Geometry', 'Discover how geometry explains mountain bike design, trail construction, angles, jumps, distances, and three-dimensional objects.', 'course', 'Mathematics', 'geo', null, array['Foundations of Geometry', 'Reasoning and Proof', 'Triangles', 'Quadrilaterals and Polygons', 'Transformations', 'Similarity and Scale', 'Circles', 'Area and Volume', 'Coordinate Geometry']::text[], array[]::text[], array[]::text[], null, 'classes/geometry/', 'all', 'available', 103),
  ('course.precalc', 'precalculus', 'Precalculus', 'Explore advanced mathematical relationships, trigonometry, functions, and mathematical modeling through the physics and geometry of mountain biking.', 'course', 'Mathematics', 'precalc', null, array['Advanced Functions', 'Polynomial and Rational Functions', 'Exponential and Logarithmic Functions', 'Trigonometry', 'Trigonometric Functions', 'Trigonometric Applications', 'Vectors', 'Parametric and Polar Functions', 'Sequences, Series, and Limits']::text[], array[]::text[], array[]::text[], null, 'classes/precalculus/', 'all', 'available', 104),
  ('course.phys1', 'trail-physics', 'Trail Physics', 'Trail Physics: the mechanics of mountain biking. Kinematics, vectors, projectile motion, Newton’s laws, friction, circular motion, energy, momentum, rotation, fluids, oscillations, waves and thermodynamics.', 'course', 'Physics', 'phys1', null, array['Physics Foundations', 'Understanding Motion', 'Forces & Cornering', 'Energy & Momentum', 'Bike Mechanics', 'Waves & Temperature']::text[], array[]::text[], array[]::text[], null, 'classes/trail-physics/', 'all', 'available', 105),
  ('course.phys2', 'trail-technology', 'Trail Technology', 'Trail Technology: electricity, magnetism and optics through e-bike motors and batteries, circuits, sensors, wireless bike computers, lights and eyewear.', 'course', 'Physics', 'phys2', null, array['Electricity', 'Magnetism & Wireless Technology', 'Light & Optics']::text[], array[]::text[], array[]::text[], null, 'classes/trail-technology/', 'all', 'available', 106),
  ('jump-lab', 'jump-lab', 'Jump Lab', 'Set the speed, angle and heights of a jump, predict where the rider lands, then send it and check the projectile-motion math.', 'lab', 'Algebra, Trigonometry, Physics', null, 'mtb', array[]::text[], array[]::text[], array['jump-lab']::text[], 'assets/jump-lab.jpg', 'learning-lab/jump-lab/', 'all', 'available', 200),
  ('berm-lab', 'berm-lab', 'Berm Lab', 'Pick a tight, middle or wide line, set your speed and bank the berm, then watch the forces, lean and grip demand of a corner change.', 'lab', 'Geometry, Trigonometry, Algebra, Physics', null, 'mtb', array[]::text[], array[]::text[], array['berm-lab']::text[], 'assets/berm-lab.jpg', 'learning-lab/berm-lab/', 'all', 'available', 201),
  ('trail-builder', 'trail-builder', 'Trail Builder', 'Design a mountain bike trail for a client, solving a math problem for every segment you build.', 'lab', 'Algebra, Geometry, Trigonometry, Statistics, Calculus', null, 'mtb', array[]::text[], array[]::text[], array['trail-builder']::text[], 'assets/trailbuilder.jpg', 'learning-lab/trail-builder/', 'all', 'available', 202),
  ('gear-ratio-lab', 'gear-ratio-lab', 'Gear Ratio Lab', 'Gear a race bike for a course, then work out ratios, speeds and times to beat a rival.', 'lab', 'Algebra, Geometry, Statistics, Calculus', null, 'mtb', array[]::text[], array[]::text[], array['gear-ratio-lab']::text[], 'assets/gear-ratio-lab.jpg', 'learning-lab/gear-ratio-lab/', 'all', 'available', 203),
  ('strava-showdown', 'strava-showdown', 'Strava Showdown', 'Be the team’s race analyst: crunch ride data, graph the field and decide who gets picked to race.', 'lab', 'Algebra, Statistics, Calculus', null, 'mtb', array[]::text[], array[]::text[], array['strava-showdown']::text[], 'assets/strava-showdown.jpg', 'learning-lab/strava-showdown/', 'all', 'available', 204),
  ('carve-lab', 'carve-lab', 'Carve Lab', 'Tip the ski, change the sidecut, speed and mass, and watch the turn radius, acceleration and force of a carved turn change on the snow.', 'lab', 'Geometry, Trigonometry, Algebra, Physics', null, 'ski', array[]::text[], array[]::text[], array['carve-lab']::text[], 'assets/carve-lab.jpg', 'learning-lab/carve-lab/', 'all', 'available', 205),
  ('slope-lab', 'slope-lab', 'Slope & Linear Relationships Lab', 'Design trails in the Trail Designer, then learn slope from rise and run, graphs, tables and y = mx + b, with practice at three levels and a no-bikes transfer challenge.', 'lab', 'Mathematics', 'alg1', 'mtb', array['Understand slope as rise over run, a rate of change', 'Calculate slope from two points, a graph and a table', 'Tell decimal slope, percentage grade and angle apart', 'Read and write y = mx + b for a trail', 'Use slope outside mountain biking']::text[], array['alg1.slope-and-rate-of-change.slope-as-rate', 'alg1.slope-and-rate-of-change.interpret-sign', 'alg1.positive-and-negative-slope.classify-slope', 'alg1.positive-and-negative-slope.direction', 'alg1.slope-and-rate-of-change.calculate-two-points', 'alg1.slope-and-rate-of-change.real-world-slope', 'geo.slope-review.calculate-slope', 'alg1.linear-relationships.constant-rate', 'alg1.linear-relationships.linear-from-table', 'alg1.linear-relationships.compare-representations', 'alg1.graphing-linear-equations.graph-slope-intercept', 'alg1.slope-intercept-form.identify-m-and-b', 'alg1.slope-intercept-form.interpret-m-and-b', 'alg1.writing-linear-equations.from-context', 'alg1.writing-linear-equations.from-two-points', 'alg1.writing-linear-equations.from-slope-and-point', 'alg1.positive-and-negative-slope.undefined-slope']::text[], array['slope-lab']::text[], null, 'learning-lab/slope-lab/', 'all', 'available', 300),
  ('jump-trajectory-lab', 'jump-trajectory-lab', 'Jump Trajectory Lab', 'Change a jump’s distance and height and watch its parabola, equation and features change together. Then decode vertex, standard and factored form and take on six jump-design missions.', 'lab', 'Mathematics', 'alg1', 'mtb', array['Recognize a jump trajectory as a parabola', 'Find the vertex and read it as the maximum height', 'Find the zeros as takeoff and landing', 'Use the axis of symmetry', 'Explain how the leading coefficient changes the shape', 'Read vertex, standard and factored form']::text[], array['alg1.graphing-quadratics.recognize-parabola', 'alg1.graphing-quadratics.graph-parabola', 'alg1.graphing-quadratics.effect-of-a', 'alg1.graphing-quadratics.read-features', 'alg1.vertex-and-axis-of-symmetry.find-vertex', 'alg1.vertex-and-axis-of-symmetry.interpret-vertex', 'alg1.solving-quadratics-by-factoring.interpret-roots', 'alg1.applications-of-quadratic-functions.reasonable-answers', 'alg1.vertex-and-axis-of-symmetry.axis-of-symmetry', 'alg1.graphing-quadratics.equation-forms']::text[], array['jump-trajectory-lab']::text[], null, 'learning-lab/jump-trajectory-lab/', 'all', 'available', 301),
  ('race-day-workshop', 'race-day-workshop', 'Race-Day Workshop', 'Join an enduro team’s technical crew: check suspension sag with formulas and absolute value, work out the speed a stage needs with rational equations, and survey a climb with a radical equation, then pass the Race-Day Certification.', 'lab', 'Mathematics', 'alg2', 'mtb', array['Translate race-prep problems into equations and inequalities', 'Rearrange a formula to isolate an unknown', 'Use absolute value as distance from a target, and rewrite it as a compound inequality', 'Solve rational equations and inequalities with a domain restriction', 'Solve radical equations and check for extraneous solutions', 'Decide whether a solution makes sense in context']::text[], array['alg2.linear-equations-review.rearrange-formulas', 'alg2.linear-equations-review.solve-linear', 'alg2.solving-equations-and-modeling-constraints.model-with-equations', 'alg2.solving-equations-and-modeling-constraints.interpret-solutions', 'alg2.solving-equations-and-modeling-constraints.compound-inequalities', 'alg2.absolute-value-equations.solve-abs-inequalities', 'alg2.absolute-value-equations.tolerance-problems', 'alg2.absolute-value-equations.solve-abs-equations', 'alg2.rational-equations.clear-denominators', 'alg2.rational-equations-applications.average-speed', 'alg2.solving-equations-and-modeling-constraints.check-solutions', 'alg2.radical-equations.extraneous', 'alg2.solving-equations-and-modeling-constraints.domain-restrictions', 'alg2.rational-equations.excluded-values', 'alg2.solving-equations-and-modeling-constraints.rational-inequalities', 'alg2.radical-equations.isolate-and-square', 'alg2.solving-equations-and-modeling-constraints.no-real-solution', 'alg2.complex-numbers.define-i', 'alg2.complex-solutions.graph-meaning']::text[], array['race-day-workshop']::text[], null, 'learning-lab/race-day-workshop/', 'all', 'available', 302),
  ('ride-systems-lab', 'ride-systems-lab', 'Ride Systems Lab', 'Become a performance engineer: read a trail’s elevation profile as a function, chain drivetrain functions from cadence to speed, transform the profile, and work backward with inverse functions, then Engineer the Ride.', 'lab', 'Mathematics', 'alg2', 'mtb', array['Explain what makes a relationship a function, and name its input and output', 'Evaluate functions from equations, tables and graphs, and find domain and range', 'Compose two functions, and explain why the order matters', 'Describe how shifts, stretches and reflections change a graph', 'Find and use an inverse, and restrict a domain so one exists']::text[], array['alg2.function-notation.evaluate-functions', 'alg2.function-notation.read-graphs-tables', 'alg2.function-notation.interpret-notation', 'alg2.function-notation.input-output', 'alg2.domain-and-range.range-from-graph', 'alg2.domain-and-range.domain-in-context', 'alg2.function-notation.increasing-decreasing', 'alg2.inverse-functions.one-to-one', 'alg2.inverse-functions.horizontal-line-test', 'alg2.composite-functions.compose', 'alg2.composite-functions.decompose', 'alg2.composite-functions.composition-order', 'alg2.transformations-of-functions.shifts', 'alg2.transformations-of-functions.stretches-reflections', 'alg2.transformations-of-functions.describe-transformations', 'alg2.inverse-functions.find-inverse', 'alg2.inverse-functions.verify-inverse', 'alg2.inverse-functions.restrict-domain', 'alg2.domain-and-range.domain-restrictions', 'alg2.composite-functions.operations-on-functions']::text[], array['ride-systems-lab']::text[], null, 'learning-lab/ride-systems-lab/', 'all', 'available', 303),
  ('bike-park-blueprint-lab', 'bike-park-blueprint-lab', 'Bike Park Blueprint Lab', 'Design a bike park with a trail crew: solve two- and three-variable systems for the build plan, run Gaussian elimination in a row-operation console, cost the whole park with matrix multiplication, and solve AX = B with an inverse.', 'lab', 'Mathematics', 'alg2', 'mtb', array['Write and solve two-variable systems by graphing, substitution and elimination', 'Tell one solution, no solution and infinitely many apart', 'Solve three-variable systems with augmented matrices and row operations', 'Add, subtract, scale and multiply matrices, checking dimensions', 'Write a system as AX = B and solve it with an inverse when det ≠ 0']::text[], array['alg2.systems-of-equations.model-systems', 'alg2.three-variable-systems.model-three', 'alg2.systems-of-equations.graph-systems', 'alg2.systems-of-equations.solve-two-variable', 'alg2.systems-of-equations.interpret-solution', 'alg2.systems-of-equations.substitution', 'alg2.systems-of-equations.elimination', 'alg2.systems-of-equations.classify-systems', 'alg2.three-variable-systems.solve-three', 'alg2.three-variable-systems.eliminate-to-two', 'alg2.three-variable-systems.augmented-matrix', 'alg2.three-variable-systems.row-operations', 'alg2.matrix-operations.dimensions', 'alg2.applications-of-matrices.organize-data', 'alg2.matrix-operations.add-scale', 'alg2.matrix-operations.multiply-matrices', 'alg2.applications-of-matrices.matrix-equations', 'alg2.matrix-operations.determinant-inverse', 'alg2.systems-of-equations.systems-of-inequalities']::text[], array['bike-park-blueprint-lab']::text[], null, 'learning-lab/bike-park-blueprint-lab/', 'all', 'available', 304),
  ('trail-dynamics-lab', 'trail-dynamics-lab', 'Trail Dynamics Lab', 'Model stopping distance as a quadratic and solve it backwards, rebuild a jump in standard, vertex and factored form, then find landing heights with square roots, completing the square, the quadratic formula and the discriminant, all the way to complex roots.', 'lab', 'Mathematics', 'alg2', 'mtb', array['Model and interpret quadratic relationships, and reject solutions outside the domain', 'Convert between standard, vertex and factored form and read each one’s features', 'Solve by square roots, factoring, completing the square and the quadratic formula', 'Use the discriminant to predict the number and type of solutions', 'Interpret complex solutions, and solve a linear–quadratic system']::text[], array['alg2.quadratic-graphs.recognize-quadratic', 'alg2.quadratic-graphs.quadratic-models', 'alg2.quadratic-graphs.transformations', 'alg2.quadratic-graphs.graph-forms', 'alg2.quadratic-graphs.convert-forms', 'alg2.quadratic-graphs.factor-zeros', 'alg2.quadratic-formula.interpret-solutions', 'alg2.quadratic-formula.use-formula', 'alg2.quadratic-formula.derive-formula', 'alg2.quadratic-formula.discriminant', 'alg2.quadratic-graphs.key-features', 'alg2.vertex-form.read-vertex-form', 'alg2.vertex-form.write-vertex-form', 'alg2.quadratic-graphs.domain-range', 'alg2.completing-the-square.square-root-property', 'alg2.completing-the-square.complete-square', 'alg2.completing-the-square.convert-to-vertex', 'alg2.complex-solutions.complex-roots', 'alg2.complex-solutions.conjugate-pairs', 'alg2.complex-solutions.graph-meaning', 'alg2.systems-of-equations.linear-quadratic', 'alg2.complex-numbers.complex-arithmetic', 'alg2.complex-numbers.define-i']::text[], array['trail-dynamics-lab']::text[], null, 'learning-lab/trail-dynamics-lab/', 'all', 'available', 305),
  ('pump-track-lab', 'pump-track-lab', 'Pump Track Profile Lab', 'Decode a pump track profile’s degree, end behavior and turning points, combine and expand polynomial profiles, find zeros and multiplicity with the Rational Zero Theorem, then divide it apart with synthetic and long division and the Remainder and Factor Theorems.', 'lab', 'Mathematics', 'alg2', 'mtb', array['Recognize polynomials and read degree, leading coefficient, end behavior and turning points', 'Add, subtract and multiply polynomials, and expand factored form to standard form', 'Find zeros, use multiplicity to tell crossing from touching, and build a polynomial from its zeros', 'Use the Rational Zero Theorem, synthetic division and long division', 'Apply the Remainder and Factor Theorems, and count complex zeros']::text[], array['alg2.polynomial-graphs.identify-polynomial', 'alg2.polynomial-graphs.degree-leading', 'alg2.polynomial-graphs.end-behavior', 'alg2.polynomial-graphs.polynomial-models', 'alg2.polynomial-graphs.turning-points', 'alg2.polynomial-graphs.zeros-multiplicity', 'alg2.polynomial-graphs.sign-intervals', 'alg2.polynomial-operations.operate', 'alg2.polynomial-operations.expand-factored', 'alg2.roots-and-zeros.zeros-factors', 'alg2.remainder-and-factor-theorems.build-polynomials', 'alg2.remainder-and-factor-theorems.factor-theorem', 'alg2.factoring-higher-degree-polynomials.factor-with-known-root', 'alg2.roots-and-zeros.rational-root-theorem', 'alg2.roots-and-zeros.find-all-zeros', 'alg2.remainder-and-factor-theorems.remainder-theorem', 'alg2.polynomial-operations.synthetic-division', 'alg2.polynomial-operations.long-division', 'alg2.roots-and-zeros.fundamental-theorem', 'alg2.complex-solutions.conjugate-pairs']::text[], array['pump-track-lab']::text[], null, 'learning-lab/pump-track-lab/', 'all', 'available', 306),
  ('enduro-route-lab', 'enduro-route-lab', 'Enduro Route Intelligence Lab', 'Model enduro stage times with rational functions: domain, asymptotes and holes, adding, subtracting, multiplying and dividing rational expressions, and solving for a target time. Then survey trail distances and wheel geometry with radical functions, transformations, rational exponents and extraneous solutions.', 'lab', 'Mathematics', 'alg2', 'mtb', array['Model inverse variation and stage times with rational functions, and read their domain, range and asymptotes', 'Add, subtract, multiply, divide and simplify rational expressions, and find removable discontinuities', 'Solve rational equations and reject candidates outside the context', 'Model distances and a wheel with radical functions; find domain, range and transformations', 'Convert rational exponents, solve radical equations, and identify extraneous solutions']::text[], array['alg2.rational-equations-applications.inverse-variation', 'alg2.graphing-rational-functions.evaluate-rational', 'alg2.rational-equations-applications.rational-models', 'alg2.rational-equations-applications.average-speed', 'alg2.graphing-rational-functions.rational-domain', 'alg2.rational-equations.excluded-values', 'alg2.asymptotes.vertical-asymptotes', 'alg2.asymptotes.horizontal-asymptotes', 'alg2.graphing-rational-functions.reciprocal-transformations', 'alg2.rational-equations-applications.solve-rational-eq', 'alg2.rational-equations.clear-denominators', 'alg2.rational-expressions.add-subtract', 'alg2.rational-expressions.simplify-rational', 'alg2.rational-expressions.multiply-divide', 'alg2.graphing-rational-functions.intercepts-holes', 'alg2.radical-functions.radical-models', 'alg2.radical-functions.radical-domain', 'alg2.radical-functions.graph-radicals', 'alg2.radical-functions.simplify-radicals', 'alg2.radical-functions.evaluate-radicals', 'alg2.radical-equations.isolate-and-square', 'alg2.radical-equations.extraneous', 'alg2.radical-functions.radical-transformations', 'alg2.radical-functions.rational-exponent-form', 'alg2.radical-equations.rational-exponents', 'alg2.asymptotes.slant-asymptotes']::text[], array['enduro-route-lab']::text[], null, 'learning-lab/enduro-route-lab/', 'all', 'available', 307),
  ('suspension-systems-lab', 'suspension-systems-lab', 'Suspension & Systems Lab', 'Model a shock’s shrinking rebound peaks as a geometric sequence and a continuous e-based envelope, forecast a trail festival’s registrations, and use logarithms, log properties and change of base to decode decibels and solve for time.', 'lab', 'Mathematics', 'alg2', 'mtb', array['Tell exponential from linear change, and identify initial values and growth or decay factors', 'Write geometric sequences explicitly and recursively, and connect them to continuous models with base e', 'Transform exponential graphs and find their asymptotes, domain and range', 'Convert between exponential and logarithmic form, and use log properties and change of base', 'Solve exponential and logarithmic equations, and interpret logarithmic scales like decibels']::text[], array['alg2.exponential-growth-and-decay.compare-models', 'alg2.geometric-sequences.arith-or-geom', 'alg2.exponential-growth-and-decay.growth-factor', 'alg2.exponential-growth-and-decay.growth-decay-models', 'alg2.applications.model-data', 'alg2.geometric-sequences.common-ratio', 'alg2.geometric-sequences.geometric-rule', 'alg2.geometric-sequences.recursive-geometric', 'alg2.exponential-functions.exponential-transformations', 'alg2.exponential-functions.graph-exponentials', 'alg2.exponential-functions.exp-domain-asymptote', 'alg2.exponential-functions.base-e', 'alg2.exponential-functions.continuous-models', 'alg2.logarithms.natural-common-logs', 'alg2.logarithmic-properties.solve-exp-log', 'alg2.exponential-growth-and-decay.solve-for-time', 'alg2.applications.doubling-half-life', 'alg2.logarithms.evaluate-logs', 'alg2.applications.sound-level', 'alg2.applications.log-scales', 'alg2.logarithms.graph-logs', 'alg2.logarithms.log-domain', 'alg2.logarithms.log-exponential-forms', 'alg2.logarithms.log-inverse', 'alg2.logarithmic-properties.expand-condense', 'alg2.logarithmic-properties.change-of-base', 'alg2.series.geometric-series']::text[], array['suspension-systems-lab']::text[], null, 'learning-lab/suspension-systems-lab/', 'all', 'available', 308),
  ('race-intelligence-lab', 'race-intelligence-lab', 'Enduro Race Intelligence Lab', 'Analyse simulated enduro race data: two-way tables, the addition rule, conditional probability and independence; mean, median, standard deviation, the normal model and z-scores; random samples, standard error and margin of error; and a seeded randomization test for an experiment.', 'lab', 'Mathematics', 'alg2', 'mtb', array['Use two-way tables for joint, marginal and conditional probabilities, the addition rule and independence', 'Compare distributions by center and spread, and use the normal model, empirical rule, z-scores and percentiles', 'Distinguish populations and samples, and estimate a proportion with standard error and margin of error', 'Distinguish surveys, observational studies and randomized experiments, and judge significance by simulation', 'Evaluate statistical claims, including why association isn’t causation']::text[], array['alg2.probability.sample-spaces', 'alg2.conditional-probability.two-way-tables', 'alg2.conditional-probability.joint-marginal', 'alg2.probability.addition-rule', 'alg2.probability.compound-events', 'alg2.probability.mutually-exclusive', 'alg2.conditional-probability.conditional-formula', 'alg2.conditional-probability.interpret-conditional', 'alg2.probability.independent-events', 'alg2.probability.multiplication-rule', 'alg2.statistical-analysis.evaluate-claims', 'alg2.statistical-analysis.center-spread', 'alg2.statistical-analysis.empirical-rule', 'alg2.statistical-analysis.normal-distribution', 'alg2.statistical-analysis.percentiles', 'alg2.statistical-analysis.populations-samples', 'alg2.statistical-analysis.sampling-distributions', 'alg2.statistical-analysis.margin-of-error', 'alg2.statistical-analysis.sampling-methods', 'alg2.statistical-analysis.study-design', 'alg2.statistical-analysis.randomization-tests', 'alg2.combinations-and-permutations.permutations', 'alg2.combinations-and-permutations.combinations']::text[], array['race-intelligence-lab']::text[], null, 'learning-lab/race-intelligence-lab/', 'all', 'available', 309),
  ('dream-line-project', 'dream-line-project', 'The Dream Line Project', 'Design your own mountain bike park, then use algebra to plan it: write and take apart the build-plan expression, substitute crew-hours, elevations, fractions and decimals, simplify the inventory with the order of operations, and use number sets and the properties of real numbers to simplify the builder’s calculations.', 'lab', 'Mathematics', 'alg1', 'mtb', array['Translate written descriptions into expressions, and identify variables, coefficients, constants and terms', 'Substitute values and evaluate expressions with integers, negatives, fractions and decimals', 'Apply the order of operations with parentheses, brackets, exponents and fraction bars, and find calculation mistakes', 'Classify numbers as natural, whole, integer, rational or irrational', 'Use the commutative, associative, identity, inverse and distributive properties, and combine like terms']::text[], array['alg1.variables-and-expressions.write-expressions', 'alg1.variables-and-expressions.identify-parts', 'alg1.properties-of-real-numbers.distributive-property', 'alg1.variables-and-expressions.interpret-expressions', 'alg1.evaluating-expressions.substitute-values', 'alg1.evaluating-expressions.evaluate-formulas', 'alg1.evaluating-expressions.evaluate-with-negatives', 'alg1.order-of-operations.apply-order', 'alg1.order-of-operations.grouping-symbols', 'alg1.order-of-operations.spot-errors', 'alg1.properties-of-real-numbers.classify-numbers', 'alg1.properties-of-real-numbers.name-properties']::text[], array['dream-line-project']::text[], null, 'learning-lab/dream-line-project/', 'all', 'available', 310),
  ('intro-to-physics', 'intro-to-physics', 'Introduction to Physics', 'Find the physics hiding on the trail, ride one run through seven physics lessons, then learn how physicists choose systems, build models and design experiments, and become a physics detective.', 'module', 'Physics', 'phys1', 'mtb', array['Explain what physics studies, with riding examples', 'Choose a physical system and say what a model leaves out', 'Plan an investigation with independent, dependent and controlled variables', 'Connect the branches of physics to the bike']::text[], array['phys1.introduction-to-physics.physics-of-the-bike', 'phys1.introduction-to-physics.what-physics-studies', 'phys1.introduction-to-physics.phenomena', 'phys1.introduction-to-physics.matter-energy', 'phys1.introduction-to-physics.systems', 'phys1.introduction-to-physics.models-and-laws', 'phys1.introduction-to-physics.observation-explanation', 'phys1.introduction-to-physics.investigation', 'phys1.introduction-to-physics.branches']::text[], array['intro-to-physics']::text[], null, 'learning-lab/intro-to-physics/', 'all', 'available', 311),
  ('newtons-laws', 'newtons-laws', 'Newton’s Laws of Motion', 'Seven short sections on forces, inertia, F = ma and action-reaction, with free-body diagrams you build yourself, the MTB Force Lab, a knowledge check and a climbing challenge.', 'module', 'Physics', 'phys1', 'mtb', array['Explain Newton’s three laws with mountain biking examples', 'Use F_net = ma and W = mg', 'Build free-body diagrams, on the flat and on a slope', 'Calculate net force and acceleration on a climb']::text[], array['phys1.newtons-laws.free-body', 'phys1.vectors.scalars-vectors', 'phys1.newtons-laws.force-and-weight', 'phys1.newtons-laws.net-force', 'phys1.newtons-laws.balanced-forces', 'phys1.newtons-laws.inertia', 'phys1.newtons-laws.second-law', 'phys1.newtons-laws.third-law', 'phys1.applications-of-newtons-laws.inclines']::text[], array['newtons-laws']::text[], null, 'learning-lab/newtons-laws/', 'all', 'available', 312),
  ('suspension-setup-studio', 'suspension-setup-studio', 'Suspension Setup Studio', 'Physics, motion and mechanical systems: what happens when a rider leaves the lip of a jump, carves a berm or compresses the fork.', 'lab', null, null, 'mtb', array[]::text[], array[]::text[], array[]::text[], null, null, 'all', 'coming_soon', 431),
  ('trail-map-navigator', 'trail-map-navigator', 'Trail Map Navigator', 'Trail design, mapping, navigation and terrain: plan a line, hit an elevation target and stay on budget.', 'lab', null, null, 'mtb', array[]::text[], array[]::text[], array[]::text[], null, null, 'all', 'coming_soon', 432),
