  ('speed-trap', 'speed-trap', 'Speed Trap', 'Performance analysis, statistics and speed: read the data, find the fastest line and back your call with numbers.', 'lab', null, null, 'mtb', array[]::text[], array[]::text[], array[]::text[], null, null, 'all', 'coming_soon', 434),
  ('bike-mechanic-challenge', 'bike-mechanic-challenge', 'Bike Mechanic Challenge', 'Bicycle mechanics and component setup: gearing, wheel sizes and the ratios that decide whether you climb or walk.', 'lab', null, null, 'mtb', array[]::text[], array[]::text[], array[]::text[], null, null, 'all', 'coming_soon', 435),
  ('gravity-friction-run', 'gravity-friction-run', 'Gravity & Friction Run', 'Gravity, friction and drag on the hill: why steeper runs are faster, how a tuck cuts air resistance and how far you fly off a kicker.', 'lab', null, null, 'ski', array[]::text[], array[]::text[], array[]::text[], null, null, 'all', 'coming_soon', 436),
